import type { ProxyNetwork } from './proxyNetwork';
export type DiagnosticEvent = {donorDomain?:string;scrolls?:number;stage?:string;elapsedMs?:number|null;screenshotState?:string;time:string;event:string;_offset?:number;_end?:number;status?:number;code?:string;service?:string;previousService?:string;provider?:string;reason?:string;errorType?:string;proxyId?:string;proxyHost?:string;proxyPort?:number;browserIp?:string;workerIp?:string;previousIp?:string;ipComparison?:string;routeComparison?:string;navigationId?:number;tab?:number;retryAfterMs?:number;durationMs?:number;url?:string};
export type LogData = {events:DiagnosticEvent[];available:boolean;truncated:boolean;invalidLines:number};
export type DiagnosticExecution = {id:string;status:string;startedAt:string|null;completedAt?:string|null;proxyId?:string|null;errorCode?:string|null;profile?:{id?:string;name:string};task?:{project:{id:string;name:string}|null}};
