export type CaptchaRequest = {service:string;startedAt:string;solutionAt:string|null;providerError:string|null;submissionError:string|null;verified:boolean;httpStatus:number|null;http429:boolean};
export type DiagnosticStage = {kind:string;label:string;startedAt:string;endedAt:string|null;durationMs:number|null;state:string;events:DiagnosticEvent[];eventCount:number;errors:number};
export type AttemptDiagnostic = {failureSnapshot:DiagnosticEvent|null;executionId:string;startedAt:string|null;profile:DiagnosticExecution['profile']|null;assignedProxy:AssignedProxy|null;network:ProxyNetwork|null;warnings:string[];coverage:Omit<LogData,'events'>&{eventCount:number};stages:DiagnosticStage[];navigation:DiagnosticEvent[];captcha:{requests:CaptchaRequest[];switches:{from:string;to:string;time:string}[]};retryAfterMs:number};
export type DiagnosticAggregate = {counts:{completed:number;failed:number;stopped:number;running:number;other:number};coverage:{selected:number;logs:number;truncated:number;invalidLines:number;observedIp:number;matchesWorker:number;withCaptcha:number};errors:{code:string;count:number}[];projects:{id:string|null;name:string;completed:number;failed:number;total:number}[];proxies:{id:string|null;label:string;total:number;completed:number;failed:number;observed:number;matchesWorker:number;ips:number}[];ips:{ip:string;total:number;failed:number;proxies:number;latestAt:string|null}[];providers:{service:string;requests:number;solutions:number;providerErrors:number;submissionErrors:number;verified:number;httpFailures:number;http429:number;latencySamples:number;medianMs:number|null;p95Ms:number|null;codes:{code:string;count:number}[]}[];switches:{from:string;to:string;count:number}[]};
export function scopedEvents(execution:DiagnosticExecution,events:DiagnosticEvent[],now?:number):DiagnosticEvent[];
export function networkForExecution(execution:DiagnosticExecution,network:ProxyNetwork|null,events:DiagnosticEvent[],now?:number):ProxyNetwork|null;
